    /// Open a font face from memory, equivalent to `FT_New_Memory_Face`.
    ///
    /// # Errors
    ///
    /// Returns [`FontError`] when `data` is unsupported or malformed, the
    /// face index is invalid, or required tables cannot be parsed.
    pub fn new_memory_face(
        self,
        data: &[u8],
        face_index: usize,
        size_pt: f32,
    ) -> Result<Face, FontError> {
        let font = Font::memory_face(data, face_index, size_pt)?;
        Ok(Face {
            font,
            render_fonts: RenderFontCache::default(),
        })
    }

    /// Open a font face with the name-selection options normally carried by
    /// `FT_Open_Face` parameters.
    ///
    /// # Errors
    ///
    /// Returns [`FontError`] under the same conditions as
    /// [`Self::new_memory_face`].

pub(crate) fn memory_face(
        data: &[u8],
        face_index: usize,
        size_pt: f32,
    ) -> Result<Self, FontError> {
        if read_u32_le(data, 0) == Some(PCF_FILE_VERSION) {
            return Self::pcf_face(data, face_index, size_pt);
        }
        if data.starts_with(b"PFR0") {
            return Self::pfr_face(data, face_index, size_pt);
        }
        if matches!(read_u16_le(data, 0), Some(0x0200) | Some(0x0300)) {
            return Self::winfnt_face(data, face_index, size_pt);
        }
        if bdf_text(data)
            .and_then(first_bdf_keyword)
            .is_some_and(is_bdf_probe_keyword)
        {
            if let Some(error) = parse_bdf_constructor_error(data) {
                return Err(error);
            }
            return Self::bdf_face(data, face_index, size_pt);
        }
        if data.starts_with(b"%!PS-Adobe-3.0 Resource-CIDFont") {
            return Self::cid_type1_face(data, face_index, size_pt);
        }

    match Self::truetype_face(data, face_index, size_pt) {
        Ok(face) => Ok(face),
        Err(error) if data.len() >= 118 => {
            // FreeType's WinFNT driver tries a standalone FNT header
            // after its MZ/NE probe fails. Its unknown-format result is
            // the final face-open error for a structurally plausible FNT
            // header with an unsupported version; unrelated malformed
            // buffers retain the earlier SFNT parser error.
            match Self::winfnt_face(data, face_index, size_pt) {
                Ok(face) => Ok(face),
                Err(FontError::UnknownFileFormat(message)) if has_winfnt_header_shape(data) => {
                    Err(FontError::UnknownFileFormat(message))
                }
                Err(_) => Err(error),
            }
        }
        Err(error) => Err(error),
    }
