    if outline.points.is_empty() || outline.n_contours == 0 {
        return Ok(RenderedBitmap {
            width: 0,
            rows: 0,
            pitch: 0,
            pixel_mode: PixelMode::Gray,
            num_grays: PixelMode::Gray.num_grays(),
            left,
            top,
            buffer: Vec::new(),
